//! Continuation/data contracts, separate from Graph→Engine business journeys.
use super::*;
use crate::{eval::FunctionLibrary,random::RandomState,scene::SceneExecution};
use std::{path::PathBuf,sync::atomic::{AtomicU64,Ordering}};
const SCOPE:&str="g732/n1:label|name=1@0,exec_out=2@0";
const EACH:&str="n2:for_each|exec_in=3@1,collection=4@0,body=5@0,completed=6@0,array_index=7@0,array_element=8@0";
fn setup()->(PreparedNarrative,SceneExecution){
    static NEXT:AtomicU64=AtomicU64::new(0);let base=PathBuf::from(std::env::var("RVN_NATIVE_NARRATIVE0732_FIXTURES").expect("isolated D fixture root required"));let path=base.join(format!("frames-{}-{}.rvn",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir_all(&base).unwrap();
    let source=format!("scene label start\nflow.consume_v3(\"{SCOPE}\",\"{EACH}\"){{for rvn_native_index_g732_n2 in [11]{{set seen=rvn_native_index_g732_n2 call helper}}}}\n\"Done\"\njump finish\nlabel helper\nreturn\nscene label child\nreturn\nscene label finish\n\"End\"\n");std::fs::write(&path,source).unwrap();let program=PreparedNarrative::from_parsed(rvn_parser::parse_file_program_with_uses(path).unwrap()).unwrap();let pc=program.script.iter().position(|s|matches!(s,rvn_parser::Statement::ScheduledConsumer{version:3,..})).unwrap();let body=program.native_loops.body(pc).unwrap();let environment=HashMap::from([(body.binding.phase.clone(),Value::Int(1)),(body.binding.cursor.clone(),Value::Int(0))]);let mut random=RandomState::seeded(732);let mut consumer=Default::default();let(input,test)=FunctionLibrary::default().eval_engine_consumer_record(&program.script[pc],&environment,&HashMap::new(),&mut random,&mut consumer,"unit-evaluator-boundary",None).unwrap();let mut cursor=DemandLoopCursor::array();assert!(cursor.enter(&input).unwrap());let mut execution=SceneExecution::new(&program);execution.enter("start",program.label_table["start"]).unwrap();execution.call_helper(program.position(pc),true).unwrap();execution.native_loop_frames_mut().0.push(NativeLoopFrame{header:program.position(pc),cursor,gather:vec![test],body_frame:0,break_site:None});execution.live_position=program.position(body.body_label+1);execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();(program,execution)
}
#[test]
fn narrative0732_real_helper_frame_parks_and_restores_loop_without_global_index(){
    let(program,mut execution)=setup();let before=execution.native_loop_frames().clone();let header=before.0[0].header.clone();let body=program.native_loops.body(header.pc).unwrap();let continuation=program.position(body.body_return);execution.call_helper(continuation.clone(),false).unwrap();execution.live_position=program.position(program.label_table["helper"]+1);assert!(execution.native_loop_frames().is_empty());assert_eq!(execution.frames.last().unwrap().parked_native_loops_v1.as_ref(),Some(&before));execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();
    execution.live_position=execution.return_to_caller(false).unwrap().unwrap();assert_eq!(execution.live_position,continuation);assert_eq!(execution.native_loop_frames(),&before);execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();execution.live_position=execution.return_to_caller(true).unwrap().unwrap();assert_eq!(execution.live_position,header);execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();assert!(execution.pre_scene_temporaries.is_empty());
}
#[test]
fn narrative0732_real_scene_call_parks_the_whole_actual_loop_activation(){
    let(program,mut execution)=setup();let old=execution.active.clone();let pc=execution.native_loop_frames().0[0].header.pc;let continuation=program.position(program.native_loops.body(pc).unwrap().body_return);execution.call_scene("child",program.label_table["child"],continuation.clone()).unwrap();execution.live_position=program.position(program.label_table["child"]+1);assert!(execution.native_loop_frames().is_empty());assert!(execution.frames.last().unwrap().parked_native_loops_v1.is_none());execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();execution.live_position=execution.return_to_caller(false).unwrap().unwrap();assert_eq!(execution.live_position,continuation);assert_eq!(execution.active.as_ref().unwrap().id,old.as_ref().unwrap().id);assert_eq!(execution.active.as_ref().unwrap().native_loop_frames_v1,old.as_ref().unwrap().native_loop_frames_v1);execution.validate(&program,&HashMap::new(),&execution.derived_call_stack()).unwrap();
}
#[test]
fn narrative0732_loop_data_cannot_borrow_an_equal_index_on_a_foreign_branch(){
    let(program,execution)=setup();let mut foreign=execution.clone();foreign.frames[0].kind=FrameKind::Helper;assert!(foreign.validate(&program,&HashMap::new(),&foreign.derived_call_stack()).is_err());let mut foreign=execution.clone();foreign.frames[0].owner=None;assert!(foreign.validate(&program,&HashMap::new(),&foreign.derived_call_stack()).is_err());let mut foreign=execution.clone();foreign.native_loop_frames_mut().0[0].body_frame=1;assert!(foreign.validate(&program,&HashMap::new(),&foreign.derived_call_stack()).is_err());let mut foreign=execution.clone();foreign.live_position=program.position(program.label_table["helper"]+1);assert!(foreign.validate(&program,&HashMap::new(),&foreign.derived_call_stack()).is_err());
}
#[test]
fn narrative0732_empty_native_fields_remain_absent_on_historical_scene_wire(){
    let program=PreparedNarrative::prepare(rvn_parser::parse("scene label start\n\"Old\"\n").unwrap()).unwrap();let mut execution=SceneExecution::new(&program);execution.enter("start",program.label_table["start"]).unwrap();execution.call_helper(program.position(1),false).unwrap();let json=serde_json::to_string(&execution).unwrap();assert!(!json.contains("native_loop_frames_v1"));assert!(!json.contains("parked_native_loops_v1"));let restored:SceneExecution=serde_json::from_str(&json).unwrap();assert!(restored.native_loop_frames().is_empty());assert!(restored.frames[0].parked_native_loops_v1.is_none());
}
